// --- Recursive Tree Component with &quot;Sculpting&quot; (Ghosting) Logic ---
const TreeBranch = ({ 
  node, x, y, spacing, depth, maxDepth, 
  activeHoverPath, currentPath = [], currentIndices = [],
  mode, logic, themeColor
}) =&gt; {
  if (!node || !node.children || node.children.length === 0 || depth &gt;= maxDepth) return null;

  const totalWidth = (node.children.length - 1) * spacing;

  return (
    &lt;g&gt;
      {node.children.map((child, i) =&gt; {
        const childX = x - totalWidth / 2 + i * spacing;
        const childY = y + 60;

        const thisPath = [...currentPath, child.name];
        const thisIndices = [...currentIndices, child.index];

        // --- VALIDITY LOGIC (The Core Pruning) ---
        // 1. Check uniqueness (for &#39;selection&#39; / no-reuse mode)
        const isUnique = new Set(thisIndices).size === thisIndices.length;

        // 2. Check sorting (for &#39;combination&#39; / order-neutral logic)
        // If combination, the indices must be in ascending order to prevent counting reverse paths.
        let isSorted = true;
        for (let j = 1; j &lt; thisIndices.length; j++) {
          if (mode === &#39;selection&#39;) {
             // Strict ascending (no duplicates allowed anyway)
             if (thisIndices[j] &lt;= thisIndices[j-1]) isSorted = false;
          } else {
             // Loose ascending (duplicates allowed)
             if (thisIndices[j] &lt; thisIndices[j-1]) isSorted = false;
          }
        }

        let isValid = true;
        if (mode === &#39;selection&#39; &amp;&amp; !isUnique) isValid = false;
        if (logic === &#39;combination&#39; &amp;&amp; !isSorted) isValid = false;

        // --- HOVER LOGIC ---
        const isPathHovered = activeHoverPath &amp;&amp; activeHoverPath[depth] === child.name &amp;&amp; activeHoverPath.join(&#39;&#39;) === thisPath.slice(0, activeHoverPath.length).join(&#39;&#39;);

        // --- STYLING LOGIC ---
        let strokeColor, strokeWidth, circleFill, textColor, zIndexClass;

        if (activeHoverPath) {
          // If the user is actively hovering a specific path from the results list
          if (isPathHovered) {
            strokeColor = themeColor;
            strokeWidth = &#39;stroke-[3px]&#39;;
            circleFill = themeColor.replace(&#39;stroke-&#39;, &#39;fill-&#39;);
            textColor = &#39;fill-white&#39;;
          } else {
            strokeColor = &#39;stroke-slate-200 opacity-20&#39;;
            strokeWidth = &#39;stroke-[1.5px]&#39;;
            circleFill = &#39;fill-white opacity-20&#39;;
            textColor = &#39;fill-slate-400 opacity-20&#39;;
          }
        } else {
          // Default State: Show validity based on current mode
          if (isValid) {
            strokeColor = themeColor;
            strokeWidth = &#39;stroke-2&#39;;
            circleFill = &#39;fill-white&#39;;
            textColor = &#39;fill-slate-700&#39;;
          } else {
            // &quot;Ghosted&quot; pruned branches
            strokeColor = &#39;stroke-slate-200 opacity-30&#39;;
            strokeWidth = &#39;stroke-[1.5px] stroke-dasharray-[2,2]&#39;;
            circleFill = &#39;fill-slate-50 opacity-50&#39;;
            textColor = &#39;fill-slate-300 opacity-50&#39;;
          }
        }

        return (
          &lt;React.Fragment key={`branch-${depth}-${i}-${child.name}`}&gt;
            &lt;line 
              x1={x} y1={y + 12} x2={childX} y2={childY - 12} 
              className={`${strokeWidth} ${strokeColor} transition-all duration-500`}
            /&gt;
            &lt;g transform={`translate(${childX}, ${childY})`}&gt;
              &lt;circle r=&quot;14&quot; className={`${circleFill} ${strokeWidth} ${strokeColor} transition-all duration-500`} /&gt;
              &lt;text 
                textAnchor=&quot;middle&quot; 
                dy=&quot;4&quot; 
                className={`text-[11px] font-bold pointer-events-none select-none ${textColor} transition-all duration-500`}
              &gt;
                {child.name}
              &lt;/text&gt;

              &lt;TreeBranch 
                node={child} 
                x={0} 
                y={0} 
                spacing={spacing * 0.45} 
                depth={depth + 1} 
                maxDepth={maxDepth}
                activeHoverPath={isPathHovered ? activeHoverPath : null}
                currentPath={thisPath}
                currentIndices={thisIndices}
                mode={mode}
                logic={logic}
                themeColor={themeColor}
              /&gt;
            &lt;/g&gt;
          &lt;/React.Fragment&gt;
        );
      })}
    &lt;/g&gt;
  );
};

const App = () =&gt; {
