    if (mode === &#39;selection&#39; &amp;&amp; logic === &#39;permutation&#39;) return { color: &#39;stroke-blue-500&#39;, bg: &#39;bg-blue-50&#39;, text: &#39;text-blue-600&#39;, name: &quot;Standard Permutations&quot; };
    if (mode === &#39;repetition&#39; &amp;&amp; logic === &#39;combination&#39;) return { color: &#39;stroke-amber-500&#39;, bg: &#39;bg-amber-50&#39;, text: &#39;text-amber-600&#39;, name: &quot;Multisets (Combos w/ Reuse)&quot; };
    if (mode === &#39;selection&#39; &amp;&amp; logic === &#39;combination&#39;) return { color: &#39;stroke-emerald-500&#39;, bg: &#39;bg-emerald-50&#39;, text: &#39;text-emerald-600&#39;, name: &quot;Standard Combinations&quot; };
  };
  const theme = getTheme();

  const mathDetails = useMemo(() =&gt; {
    const n = totalItems;
    const r = groupSize;
    if (mode === &#39;selection&#39; &amp;&amp; logic === &#39;permutation&#39;) {
      return { notation: `P(${n},${r})`, formula: `n! / (n-r)!`, count: fact(n) / fact(n - r) };
    } else if (mode === &#39;selection&#39; &amp;&amp; logic === &#39;combination&#39;) {
      return { notation: `C(${n},${r})`, formula: `n! / [r!(n-r)!]`, count: fact(n) / (fact(r) * fact(n - r)) };
    } else if (mode === &#39;repetition&#39; &amp;&amp; logic === &#39;permutation&#39;) {
      return { notation: `n^r`, formula: `n^r`, count: Math.pow(n, r) };
    } else {
      return { notation: `C(${n}+${r}-1, ${r})`, formula: `(n+r-1)! / [r!(n-1)!]`, count: fact(n + r - 1) / (fact(r) * fact(n - 1)) };
    }
  }, [totalItems, groupSize, mode, logic]);

  // GENERATE THE MASTER TREE DATA (Always n^r, allowing everything)
  const masterTreeData = useMemo(() =&gt; {
