    const build = (node, depth) =&gt; {
      if (depth === groupSize) return;
      items.forEach((item, idx) =&gt; {
        const child = { name: item, index: idx, children: [] };
        node.children.push(child);
        if (depth &lt; 3) build(child, depth + 1); // Cap depth for SVG safety
      });
    };
    build(root, 0);
    return root;
  }, [items, groupSize]);

  // Generate only the VALID paths for the results list
  const validPaths = useMemo(() =&gt; {
    let res = [];
    const bt = (currPath, currIndices) =&gt; {
      if (currPath.length === groupSize) {
        // Validate against current rules before pushing
        const isUnique = new Set(currIndices).size === currIndices.length;
        let isSorted = true;
        for (let j = 1; j &lt; currIndices.length; j++) {
          if (mode === &#39;selection&#39; &amp;&amp; currIndices[j] &lt;= currIndices[j-1]) isSorted = false;
          if (mode === &#39;repetition&#39; &amp;&amp; currIndices[j] &lt; currIndices[j-1]) isSorted = false;
        }

        let isValid = true;
        if (mode === &#39;selection&#39; &amp;&amp; !isUnique) isValid = false;
        if (logic === &#39;combination&#39; &amp;&amp; !isSorted) isValid = false;

        if (isValid) res.push([...currPath]);
        return;
      }

      items.forEach((item, idx) =&gt; {
        currPath.push(item);
        currIndices.push(idx);
        bt(currPath, currIndices);
        currPath.pop();
        currIndices.pop();
      });
    };
    bt([], []);
    return res;
  }, [items, groupSize, mode, logic]);


