                    onClick={() =&gt; setMode(&#39;repetition&#39;)}
                    className={`py-3 px-2 rounded-2xl border text-xs font-bold transition-all flex flex-col items-center text-center ${mode === &#39;repetition&#39; ? &#39;bg-slate-800 text-white border-slate-800 shadow-md&#39; : &#39;bg-slate-50 text-slate-500 border-slate-100 hover:border-slate-300&#39;}`}
                  &gt;
                    &lt;RefreshCcw size={16} className=&quot;mb-2&quot; /&gt;
                    Infinite (Reuse)
                  &lt;/button&gt;
                  &lt;button 
                    onClick={() =&gt; setMode(&#39;selection&#39;)}
                    className={`py-3 px-2 rounded-2xl border text-xs font-bold transition-all flex flex-col items-center text-center ${mode === &#39;selection&#39; ? &#39;bg-slate-800 text-white border-slate-800 shadow-md&#39; : &#39;bg-slate-50 text-slate-500 border-slate-100 hover:border-slate-300&#39;}`}
                  &gt;
                    &lt;Users size={16} className=&quot;mb-2&quot; /&gt;
                    Finite (No Reuse)
                  &lt;/button&gt;
                &lt;/div&gt;
              &lt;/div&gt;

